#include "mock_pins.h"

static int      s_stat_level;
static int      s_pg_level;
static int      s_alert_level;
static int      s_vbus_level;
static uint8_t  s_fail_stat;
static uint8_t  s_fail_pg;
static uint8_t  s_fail_alert;
static uint32_t s_read_count;

void MockPins_Reset(void)
{
    /* Open-drain lines idle HIGH under their pull-ups. */
    s_stat_level  = 1;
    s_pg_level    = 1;
    s_alert_level = 1;
    s_vbus_level  = 0;
    s_fail_stat   = 0U;
    s_fail_pg     = 0U;
    s_fail_alert  = 0U;
    s_read_count  = 0U;
}

void MockPins_SetStat(int level)  { s_stat_level = level; }
void MockPins_SetPg(int level)    { s_pg_level = level; }
void MockPins_SetAlert(int level) { s_alert_level = level; }
void MockPins_SetVbus(int level)  { s_vbus_level = level; }

void MockPins_FailStat(uint8_t fail)  { s_fail_stat = fail; }
void MockPins_FailPg(uint8_t fail)    { s_fail_pg = fail; }
void MockPins_FailAlert(uint8_t fail) { s_fail_alert = fail; }

static int mock_read_stat(void *ctx)
{
    (void)ctx;
    s_read_count++;
    return (s_fail_stat != 0U) ? -1 : s_stat_level;
}

static int mock_read_pg(void *ctx)
{
    (void)ctx;
    s_read_count++;
    return (s_fail_pg != 0U) ? -1 : s_pg_level;
}

static int mock_read_alert(void *ctx)
{
    (void)ctx;
    s_read_count++;
    return (s_fail_alert != 0U) ? -1 : s_alert_level;
}

static int mock_read_vbus(void *ctx)
{
    (void)ctx;
    s_read_count++;
    return s_vbus_level;
}

static const Charger_Pins s_iface = {
    mock_read_stat,
    mock_read_pg,
    mock_read_alert,
    mock_read_vbus,
    (void *)0,
};

static const Charger_Pins s_iface_no_vbus = {
    mock_read_stat,
    mock_read_pg,
    mock_read_alert,
    (int (*)(void *))0,
    (void *)0,
};

const Charger_Pins *MockPins_Iface(void)       { return &s_iface; }
const Charger_Pins *MockPins_IfaceNoVbus(void) { return &s_iface_no_vbus; }

uint32_t MockPins_ReadCount(void) { return s_read_count; }
